import java.util.*;

class Solution {
    public ListNode removeNthFromEnd(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head);
        ListNode lead = dummy, trail = dummy;
        for (int i = 0; i < k; i++) lead = lead.next;   // give lead a k-node head start
        while (lead.next != null) {                     // stop when lead is on the last node
            lead = lead.next;
            trail = trail.next;
        }
        trail.next = trail.next.next;                   // skip the k-th from the end
        return dummy.next;
    }
}
